import {pages,videos,channel} from './content.js';
const scene=document.querySelector('#scene');
const icons={about:'<circle cx="16" cy="10" r="5"/><path d="M6 28v-5a10 10 0 0 1 20 0v5Z"/>',career:'<rect x="4" y="10" width="24" height="18"/><path d="M11 10V5h10v5M4 18h24M13 16v5h6v-5"/>',design:'<path d="m16 3 13 8v13l-13 7L3 24V11ZM3 11l13 8 13-8M16 19v12M9 7l14 8"/>',content:'<rect x="3" y="7" width="26" height="19"/><path d="m13 12 8 5-8 5Z"/>'};
const categories=[['about','About Me','The person behind the work'],['career','Career Experience','Where I’ve been building'],['design','Design Projects','From possibility to reality'],['content','Content Creation','Ideas, made understandable']];
function home(){scene.innerHTML=`<div class="intro"><div class="home-world"><svg class="connections" viewBox="0 0 1150 600"><path class="line-about" d="M142 96V145H300V205"/><path class="line-career" d="M900 110V143H850V205"/><path class="line-design" d="M152 454V404H300V365"/><path class="line-content" d="M907 446V404H850V365"/></svg><div class="dither"></div><section class="root-card"><img class="portrait" src="assets/portrait.jpg" alt="Zac in the ZXTECH studio"><div class="identity"><span class="micro">ZX / 00</span><span class="mark">⌖</span><h1>Zac Ong<br>Zhi Xing</h1><p>FUTURIST</p></div></section>${categories.map(([id,title,sub],i)=>`<a class="orbit ${id}" href="#${id}"><span class="node-symbol"><svg viewBox="0 0 32 34" aria-hidden="true">${icons[id]}</svg></span><b>${title} <span style="font-size:12px">↗</span></b><span class="micro">0${i+1} / ${sub}</span></a>`).join('')}<span class="coordinate">[ 0, 0 ] — EVERYTHING IS CONNECTED.</span></div></div>`;}
const viewport=document.querySelector('#viewport');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const symbol=id=>`<svg viewBox="0 0 32 34" aria-hidden="true">${icons[id]||icons.design}</svg>`;
let current='home',previous='home',mapState={x:0,y:0,scale:1};
function breadcrumbs(id){let list=[],p=pages[id];while(p){list.unshift([id,p.title]);id=p.parent;p=pages[id];}return `<div class="breadcrumbs"><a href="#home">ZX</a>${list.map(([key,title],i)=>`<span>/</span>${i===list.length-1?`<span aria-current="page">${esc(title)}</span>`:`<a href="#${key}">${esc(title)}</a>`}`).join('')}</div>`;}
function sectionTitle(p,small=''){return `<div class="section-title"><span class="micro">${small||esc(p.sub)}</span><h1 tabindex="-1">${esc(p.title)}</h1>${small?`<p>${esc(p.sub)}</p>`:''}<span class="title-cross" aria-hidden="true">+</span></div>`;}
function thumb(p){return p.image||p.images?.[0]||(p.kind==='video'?`assets/${p.id}.jpg`:null);}
function nodeLink(id,index=0){const p=pages[id],src=thumb(p);return `<a class="project-node ${src?'has-image':'no-image'}" href="#${id}"><span class="port top-port"></span><div class="node-preview">${src?`<img src="${src}" alt="${esc(p.captions?.[0]||p.title)}" loading="lazy">`:`<div class="node-art" aria-hidden="true">${p.kind==='branch'?symbol('design'):symbol(id==='law'?'career':'design')}<span>${String(index+1).padStart(2,'0')}</span></div>`}${p.status?`<span class="status">${p.status}</span>`:''}<span class="node-arrow" aria-hidden="true">↗</span></div><div class="node-copy"><span class="micro">${String(index+1).padStart(2,'0')} / ${p.kind==='branch'?'DIRECTION':p.parent==='career'?'EXPERIENCE':'PROJECT'}</span><h2>${esc(p.title)}</h2><p>${esc(p.sub)}</p></div></a>`;}
function branch(id){const p=pages[id];scene.innerHTML=`<div class="view branch-view">${breadcrumbs(id)}<div class="branch-root">${sectionTitle(p)}<span class="stem"></span></div><div class="branch-nodes count-${p.children.length}">${p.children.map(nodeLink).join('')}</div></div>`;}
function placeholder(title){return `<section class="writeup-box"><div class="box-caption"><span>${esc(title)}</span><span aria-hidden="true">+</span></div><div class="writeup-content"><p class="empty-copy">Write-up coming soon.</p><div class="blank-lines" aria-hidden="true"><i></i><i></i><i></i></div></div></section>`;}
function about(){const p=pages.about;scene.innerHTML=`<div class="view about-view">${breadcrumbs('about')}<div class="about-main"><figure class="portrait-box"><div class="box-caption">01 / ABOUT ME<span>ZX</span></div><img src="assets/portrait.jpg" alt="Zac in the ZXTECH studio"><figcaption>Zac Ong Zhi Xing</figcaption></figure><div class="about-copy">${sectionTitle(p,'ZAC ONG ZHI XING')}${p.body?`<div class="writeup-box filled">${esc(p.body)}</div>`:placeholder('A little about me')}</div></div><div class="simple-branches">${p.children.map((id,i)=>`<a class="small-node" href="#${id}"><span class="micro">0${i+1}</span><strong>${esc(pages[id].title)}</strong><span>↗</span></a>`).join('')}</div></div>`;}
function mediaBox(p){const src=thumb(p);return `<figure class="media-box"><div class="box-caption"><span>${p.status||'PROJECT ARCHIVE'}</span><span>${src?'01 / '+String(p.images?.length||1).padStart(2,'0'):'TO ADD'}</span></div>${src?`<button class="image-open" data-src="${src}" data-caption="${esc(p.captions?.[0]||p.title)}" aria-label="Enlarge ${esc(p.title)} image"><img class="hero-media ${p.parent==='career'?'career-media':''} ${p.title==='Aftershock M1 Pro'?'contain':''}" src="${src}" alt="${esc(p.captions?.[0]||p.title)}"><span class="enlarge">↗</span></button><figcaption>${esc(p.captions?.[0]||p.title)}</figcaption>`:`<div class="media-empty"><span class="empty-grid" aria-hidden="true"></span><span>${esc(p.mediaPlaceholder||'Images to add')}</span><span class="micro">SPACE FOR THE STORY</span></div>`}</figure>`;}
function gallery(p){return (p.images?.length||0)>1?`<section class="gallery"><div class="gallery-label micro">PROCESS & DETAILS <span>${p.images.length-1} IMAGES</span></div><div class="gallery-grid">${p.images.slice(1).map((src,i)=>`<figure class="gallery-item"><button class="image-open" data-src="${src}" data-caption="${esc(p.captions?.[i+1]||p.title)}" aria-label="Enlarge ${esc(p.captions?.[i+1]||p.title)}"><img src="${src}" loading="lazy" alt="${esc(p.captions?.[i+1]||p.title)}"><span class="enlarge">↗</span></button><figcaption>${String(i+2).padStart(2,'0')} / ${esc(p.captions?.[i+1]||'Process image')}</figcaption></figure>`).join('')}</div></section>`:'';}
function detail(id){const p=pages[id];scene.innerHTML=`<div class="view detail-view">${breadcrumbs(id)}${sectionTitle(p)}<div class="detail-grid"><div>${mediaBox(p)}${p.source?`<a class="source-link" href="${p.source.url}" target="_blank" rel="noopener">${esc(p.source.title)} ↗</a>`:''}</div><div class="writeup-stack">${p.body?`<section class="writeup-box filled">${esc(p.body).replace(/\n/g,'<br>')}</section>`:(p.prompts||['Overview','Process','Reflections']).map(placeholder).join('')}</div></div>${gallery(p)}${p.related?`<div class="related-line"><span class="micro">CONNECTED TO</span><a class="small-node" href="#${p.related}"><strong>${esc(pages[p.related].title)}</strong><span>↗</span></a></div>`:''}<a class="return-link" href="#${p.parent}">↖ Back to ${esc(pages[p.parent].title)}</a></div>`;}
function content(){const p=pages.content;scene.innerHTML=`<div class="view content-view">${breadcrumbs('content')}<div class="content-intro"><div>${sectionTitle(p)}<div class="mission-box"><h2>Bring the future<br>to the people.</h2><p>Design, testing, and technology made clearer.</p><p>A decade of explaining, filming, testing, and listening—shaped by industrial design at NUS and experience leading TECHYARD.</p></div></div><figure class="creator-image"><img src="assets/portrait.jpg" alt="Zac presenting in the ZXTECH studio"><figcaption><span>ZXTECH</span><span>INFORM / DESIGN / EXCITE / EDUCATE</span></figcaption></figure></div><div class="analytics-row">${[[channel.experience,'YEARS CREATING'],[channel.subscribers,'SUBSCRIBERS'],['4.79M','CHANNEL VIEWS'],[channel.videos,'VIDEOS PUBLISHED']].map(([value,label])=>`<div class="metric"><strong>${value}</strong><span>${label}</span></div>`).join('')}</div><p class="source-note">Public YouTube snapshot · ${channel.checked} · ${channel.views} views · <a href="${channel.url}" target="_blank" rel="noopener">View channel ↗</a></p><div class="analytics-placeholders">${placeholder('Audience & watch time')}${placeholder('Reach & impact')}</div><div class="sequence-start"><span class="micro">SEVEN FILMS / ONE CONNECTED JOURNEY</span><a class="next-node" href="#video-headphones"><span><span class="micro">BEGIN THE SEQUENCE · 01 / 07</span><strong>Headphones, redesigned</strong><small>Putting My Vision to work</small></span><span class="next-arrow">→</span></a></div></div>`;}
function video(id){const p=pages[id],next=videos[p.index+1];scene.innerHTML=`<div class="view video-view"><div class="breadcrumbs"><a href="#home">ZX</a><span>/</span><a href="#content">Content Creation</a><span>/</span><span>${String(p.index+1).padStart(2,'0')} OF 07</span></div><div class="video-heading"><div><span class="micro">${esc(p.sub)}</span><h1 tabindex="-1">${esc(p.short)}</h1></div><div class="sequence-count"><b>${String(p.index+1).padStart(2,'0')}</b><span>/ 07</span></div></div><div class="video-layout"><div class="video-frame" id="video-player"><button class="play-video" data-video="${p.id}" aria-label="Play ${esc(p.title)}"><img src="assets/${p.id}.jpg" alt="${esc(p.title)} thumbnail"><span class="play-disc"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 4 13 8-13 8Z" fill="currentColor"/></svg></span><span class="play-label">PLAY FILM</span></button></div><aside class="video-info"><div class="box-caption">ZXTECH / ${p.year}</div><div class="video-info-body"><h2>${esc(p.title)}</h2><p>${esc(p.sub)}</p><a class="source-link" href="https://www.youtube.com/watch?v=${p.id}" target="_blank" rel="noopener">Watch on YouTube ↗</a></div>${placeholder('Behind this film')}</aside></div><div class="sequence-progress" aria-label="Film ${p.index+1} of 7">${videos.map((v,i)=>`<span class="${i<=p.index?'done':''}" aria-hidden="true"></span>`).join('')}</div><div class="sequence-next"><span class="micro">${next?'FOLLOW THE CONNECTION':'YOU’VE REACHED THE END'}</span><a class="next-node" href="#${next?next.slug:'content'}"><span><span class="micro">${next?`UP NEXT · ${String(p.index+2).padStart(2,'0')} / 07`:'BACK TO CONTENT CREATION'}</span><strong>${next?esc(next.short):'A decade. Still curious.'}</strong><small>${next?esc(next.sub):'Explore the channel & its impact'}</small></span><span class="next-arrow">→</span></a></div></div>`;}
function collectMap(){
 const nodes=[{id:'home',title:'Zac Ong Zhi Xing',x:930,y:0,w:260,h:96,root:true}],edges=[];
 const add=(id,x,y)=>{const p=pages[id];nodes.push({id,title:p.short||p.title,x,y,w:260,h:96,sub:p.sub});};
 add('about',0,250);edges.push(['home','about']);pages.about.children.forEach((id,i)=>{add(id,0,450+i*145);edges.push(['about',id]);});
 add('career',340,250);edges.push(['home','career']);pages.career.children.forEach((id,i)=>{add(id,340,450+i*145);edges.push(['career',id]);});
 add('design',1120,250);edges.push(['home','design']);pages.design.children.forEach((id,i)=>{const x=760+i*360;add(id,x,450);edges.push(['design',id]);pages[id].children.forEach((child,j)=>{add(child,x,640+j*145);edges.push([id,child]);});});
 add('content',1920,250);edges.push(['home','content']);videos.forEach((v,i)=>{add(v.slug,1920,450+i*145);edges.push([i?videos[i-1].slug:'content',v.slug]);});return {nodes,edges};
}
const graph=collectMap();
function overview(){scene.innerHTML=`<div class="map-view"><div class="map-heading"><span class="micro">THE WHOLE PICTURE</span><h1>Everything is connected.</h1><p>Drag to move · Scroll to zoom · Select any node</p></div><div class="graph-stage" id="graph-stage"><svg class="graph-edges" overflow="visible">${graph.edges.map(([from,to])=>{const a=graph.nodes.find(n=>n.id===from),b=graph.nodes.find(n=>n.id===to);return `<path d="M ${a.x+a.w/2} ${a.y+a.h/2} C ${a.x+a.w/2} ${b.y+b.h/2},${b.x+b.w/2} ${a.y+a.h/2},${b.x+b.w/2} ${b.y+b.h/2}"/>`;}).join('')}</svg>${graph.nodes.map(n=>`<a href="#${n.id}" class="graph-node ${n.root?'graph-root':''} ${n.id===previous?'selected':''}" style="left:${n.x}px;top:${n.y}px;width:${n.w}px;height:${n.h}px"><span class="port"></span><strong>${esc(n.title)}</strong><span class="micro">${n.root?'FUTURIST':esc(n.sub||'')}</span></a>`).join('')}</div><div class="map-controls"><button id="zoom-out" aria-label="Zoom out">−</button><span id="zoom-label">100%</span><button id="zoom-in" aria-label="Zoom in">+</button><button id="fit-map">FIT ALL</button><button id="map-return">RETURN ↗</button></div></div>`;setupMap();}
function drawMap(){const st=document.querySelector('#graph-stage');if(!st)return;st.style.transform=`translate(${mapState.x}px,${mapState.y}px) scale(${mapState.scale})`;document.querySelector('#zoom-label').textContent=Math.round(mapState.scale*100)+'%';}
function fitMap(){const w=viewport.clientWidth,h=viewport.clientHeight;const minX=-60,maxX=2240,minY=-120,maxY=1490;const scale=Math.min((w-70)/(maxX-minX),(h-160)/(maxY-minY),.65);mapState={scale,x:(w-(maxX+minX)*scale)/2,y:100+(h-150-(maxY+minY)*scale)/2};drawMap();}
function zoom(factor,cx=viewport.clientWidth/2,cy=viewport.clientHeight/2){const old=mapState.scale,scale=Math.max(.075,Math.min(1.6,old*factor));mapState.x=cx-(cx-mapState.x)*scale/old;mapState.y=cy-(cy-mapState.y)*scale/old;mapState.scale=scale;drawMap();}
function setupMap(){fitMap();const surface=document.querySelector('.map-view');let points=new Map(),drag=null,moved=false;
 document.querySelector('#zoom-in').onclick=()=>zoom(1.35);document.querySelector('#zoom-out').onclick=()=>zoom(1/1.35);document.querySelector('#fit-map').onclick=fitMap;document.querySelector('#map-return').onclick=()=>location.hash=previous==='map'?'home':previous;
 surface.addEventListener('wheel',e=>{e.preventDefault();const r=surface.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top);},{passive:false});
 surface.addEventListener('pointerdown',e=>{if(e.target.closest('.map-controls'))return;points.set(e.pointerId,{x:e.clientX,y:e.clientY});drag={x:e.clientX,y:e.clientY,tx:mapState.x,ty:mapState.y};moved=false;});
 surface.addEventListener('pointermove',e=>{if(!points.has(e.pointerId))return;const prev=points.get(e.pointerId);if(points.size===2){const other=[...points.entries()].find(([id])=>id!==e.pointerId)[1];const old=Math.hypot(prev.x-other.x,prev.y-other.y);const now=Math.hypot(e.clientX-other.x,e.clientY-other.y);const r=surface.getBoundingClientRect();zoom(now/old,(e.clientX+other.x)/2-r.left,(e.clientY+other.y)/2-r.top);moved=true;}else if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>5){moved=true;surface.setPointerCapture(e.pointerId);mapState.x=drag.tx+dx;mapState.y=drag.ty+dy;drawMap();}}points.set(e.pointerId,{x:e.clientX,y:e.clientY});});
 const end=e=>{points.delete(e.pointerId);drag=null;};surface.addEventListener('pointerup',end);surface.addEventListener('pointercancel',end);surface.addEventListener('click',e=>{if(moved&&!e.target.closest('.map-controls')){e.preventDefault();moved=false;}},true);
}
const modal=document.createElement('dialog');modal.className='lightbox';modal.innerHTML='<button class="close-lightbox" aria-label="Close image">CLOSE ×</button><figure><img alt=""><figcaption></figcaption></figure>';document.body.append(modal);modal.querySelector('button').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal)modal.close();};
scene.addEventListener('click',e=>{const b=e.target.closest('.image-open');if(b){modal.querySelector('img').src=b.dataset.src;modal.querySelector('img').alt=b.dataset.caption;modal.querySelector('figcaption').textContent=b.dataset.caption;modal.showModal();}const play=e.target.closest('.play-video');if(play){const p=pages[current];document.querySelector('#video-player').innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${play.dataset.video}?autoplay=1&rel=0" title="${esc(p.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;}});
document.querySelector('.skip').onclick=e=>{e.preventDefault();document.querySelector('#content').focus();};
document.querySelector('#home').onclick=()=>location.hash='home';document.querySelector('#back').onclick=()=>location.hash=current==='map'?previous:(pages[current]?.parent||'home');document.querySelector('#map').onclick=()=>location.hash=current==='map'?previous:'map';
window.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.matches('input,textarea,[contenteditable]')||modal.open)return;const key=e.key.toLowerCase();if(key==='h'){e.preventDefault();location.hash='home';}if(key==='m'){e.preventDefault();location.hash=current==='map'?previous:'map';}if(key==='escape'&&current!=='home'){e.preventDefault();document.querySelector('#back').click();}if(current==='map'){if(e.key==='+')zoom(1.25);if(e.key==='-')zoom(.8);if(e.key==='0')fitMap();}});
function route(){const id=decodeURIComponent(location.hash.slice(1))||'home';if(id!=='home'&&id!=='map'&&!pages[id]){location.replace('#home');return;}if(current!=='map'&&id==='map')previous=current;current=id;scene.className=id==='home'?'home-scene':id==='map'?'map-scene':'page-scene';viewport.scrollTo(0,0);document.querySelector('#map').classList.toggle('active',id==='map');document.querySelector('#home').classList.toggle('active',id==='home');document.querySelector('#back').disabled=id==='home';document.querySelector('#location').textContent=id==='home'?'00 / HOME':id==='map'?'00 / GLOBAL MAP':(pages[id].kind==='video'?'04':id==='about'||pages[id].parent==='about'?'01':id==='career'||pages[id].parent==='career'?'02':id==='content'?'04':'03')+' / '+(pages[id].short||pages[id].title).toUpperCase();document.querySelector('#hint').textContent=id==='map'?'DRAG / ZOOM / EXPLORE':id==='home'?'SELECT A NODE TO EXPLORE':'ESC BACK · H HOME · M MAP';document.title=(id==='home'?'ZX — Zac Ong Zhi Xing':id==='map'?'Global Map — ZX':pages[id].title+' — ZX');if(id==='home')home();else if(id==='map')overview();else if(id==='about')about();else if(id==='content')content();else if(pages[id].kind==='branch')branch(id);else if(pages[id].kind==='video')video(id);else detail(id);requestAnimationFrame(()=>{if(id!=='home'&&id!=='map')scene.querySelector('h1')?.focus({preventScroll:true});});}
window.addEventListener('hashchange',route);window.addEventListener('resize',()=>{if(current==='map')fitMap();});route();
